    "8aba50eb": {"text":"Il mandato dei servizi domestici","hash":"h1-97115bcf"},
    "8aba718f": {"text":"Regno di Croazia","hash":"h1-c36ee0fe"},
    "8abb4e5b": {"text":"Whithorn","hash":"h1-e0e7845a"},
    "8ac9a888": {"text":"Il viaggio costa {money:cost}; hai {money:current}.","hash":"h1-85f4bb22"},
    "8aca0401": {"forms":{"select":"value","param":"rank","cases":{"officer":"🏅 {name} vince le elezioni della gilda e inizia un mandato fisso come ufficiale.","guildmaster":"🏅 {name} vince le elezioni della gilda e inizia un mandato fisso come capogilda.","other":"🏅 {name} vince le elezioni della gilda e inizia un mandato fisso."}},"hash":"h1-2c26b502"},
